// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createBulkArchiveJob,
    deleteLink,
    deleteCollection,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collectionsPostResponse = await createCollection(client, headers, "testbot-bulk-archive-dup-col");
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("testbot-bulk-archive-dup-col");
    expect(Number(getResponseValue(collectionsPostResponse, "response.id")), 'id').toBeGreaterThan(0);

    const linksPostResponse = await createLink(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id"),
        "testbot-bulk-archive-dup-link",
        "https://example.com/testbot-bulk-archive-dup"
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("testbot-bulk-archive-dup-link");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/testbot-bulk-archive-dup");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(getResponseValue(collectionsPostResponse, "response.id"));

    // The caller owns every id in the batch, so repeating it must not turn the batch into a
    // permission failure.
    const bulkArchivePostResponse = await createBulkArchiveJob(client, headers, [
        getResponseValue(linksPostResponse, "response.id"),
        getResponseValue(linksPostResponse, "response.id"),
    ]);
    expect(bulkArchivePostResponse.statusCode, 'status code').toBe(202);
    expect(getResponseValue(bulkArchivePostResponse, "response.jobId"), 'jobId').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    expect(getResponseValue(bulkArchivePostResponse, "response.status"), 'status').toBe("queued");
    expect(getResponseValue(bulkArchivePostResponse, "response"), 'the batch is not refused as inaccessible').not.toBe("One or more links are not accessible.");

    const linksLinksDeleteResponse = await deleteLink(client, headers, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'id').toBe(getResponseValue(linksPostResponse, "response.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
